create or replace function public.manager_list_company_users(p_company_id uuid) returns table(record_id uuid,user_id uuid,email text,role text,status text,kind text,created_at timestamptz,expires_at timestamptz,is_self boolean) language plpgsql security definer set search_path='public','auth','pg_temp' as $$ begin if not private.can_manage_company_users(p_company_id) then raise exception 'Nicht berechtigt'; end if; update public.company_member_invites i set status='EXPIRED' where i.company_id=p_company_id and i.status='INVITED' and i.expires_at<=now(); return query select cm.user_id,cm.user_id,coalesce(u.email,''),cm.role,cm.status,'MEMBER',cm.created_at,null::timestamptz,cm.user_id=auth.uid() from public.company_members cm join auth.users u on u.id=cm.user_id where cm.company_id=p_company_id union all select i.id,null::uuid,i.email,i.role,i.status,'INVITE',i.created_at,i.expires_at,false from public.company_member_invites i where i.company_id=p_company_id and i.status in ('INVITED','EXPIRED') order by created_at; end $$; revoke all on function public.manager_list_company_users(uuid) from public,anon; grant execute on function public.manager_list_company_users(uuid) to authenticated;;
